INSERT INTO Book (bno, b_name, ISBN, press, category_id, year, author, total, stock, location, description) VALUES
(111, 'Beowulf', '9780140433777', 'HarperCollins Publishers', 1, 1975, 1, 10, 10, 'Rush Rhees', 'An epic poem from the Anglo-Saxon period, "Beowulf" narrates the heroic deeds of its titular character, who battles the monstrous Grendel, Grendel''s mother, and later, a dragon. This foundational work explores themes of heroism, loyalty, and the struggle between good and evil.'),
(112, 'Batman: Year One', '9781401272944', 'HarperCollins Publishers', 1, 1987, 2, 10, 10, 'Rush Rhees', 'A graphic novel by Frank Miller and David Mazzucchelli, "Batman: Year One" chronicles Bruce Wayne''s first year as Batman, detailing his initial struggles against crime and the formation of his alliance with Lieutenant James Gordon.'),
(113, 'Go Set a Watchman', '9780062409850', 'Amazon Digital Services, Inc.', 1, 2015, 3, 10, 10, 'Rush Rhees', 'Written by Harper Lee, this novel serves as a sequel to "To Kill a Mockingbird." Set two decades later, it follows Scout Finch as she returns to Maycomb, Alabama, confronting personal and political issues that challenge her perceptions of her father and hometown.'),
(114, 'When You Are Engulfed in Flames', '9780316154680', 'Hachette Book Group', 1, 2008, 4, 10, 10, 'Rush Rhees', 'A collection of essays by David Sedaris, offering humorous and poignant reflections on various aspects of life, including personal anecdotes, observations, and experiences.'),
(115, 'Daughter of Smoke & Bone', '9780316134026', 'Penguin Group (USA) LLC', 1, 2011, 5, 10, 10, 'Rush Rhees', 'Authored by Laini Taylor, this fantasy novel introduces Karou, a young art student in Prague who becomes entangled in a cosmic war between angels and chimera, uncovering secrets about her own mysterious past.'),
(116, 'Red Queen', '9780062310637', 'Amazon Digital Services, Inc.', 1, 2015, 6, 10, 10, 'Rush Rhees', 'Victoria Aveyard''s dystopian fantasy centers on Mare Barrow, a young woman with red blood in a society where the silver-blooded elite possess supernatural abilities. Mare discovers her own hidden powers, challenging the established social order.'),
(117, 'The Power of Habit', '9780812981605', 'HarperCollins Publishers', 1, 2011, 7, 10, 10, 'Rush Rhees', 'In this nonfiction work, Charles Duhigg explores the science behind habit formation and change, providing insights into how habits work and how they can be transformed to improve personal and professional lives.'),
(118, 'Midnight in the Garden of Good and Evil', '9780679751526', 'Hachette Book Group', 1, 1994, 8, 10, 10, 'Rush Rhees', 'John Berendt''s nonfiction narrative delves into the eccentricities of Savannah, Georgia, culminating in a gripping murder trial that exposes the city''s hidden facets.'),
(119, 'Hopeless', '9781476743554', 'HarperCollins Publishers', 1, 2012, 9, 10, 10, 'Rush Rhees', 'A novel by Colleen Hoover, it follows Sky, a teenager with a troubled past, as she meets Dean Holder, leading to revelations that challenge her understanding of her life and relationships.'),
(120, 'A Little Princess', '9780142437018', 'Random House LLC', 1, 1905, 10, 10, 10, 'Rush Rhees', 'Frances Hodgson Burnett''s classic tells the story of Sara Crewe, a young girl who, after losing her wealth, maintains her kindness and imagination, transforming her grim circumstances at a boarding school.'),
(121, 'The Truth About Forever', '9780142406250', 'Amazon Digital Services, Inc.', 1, 2004, 11, 10, 10, 'Rush Rhees', 'Sarah Dessen''s young adult novel follows Macy Queen, a teenager coping with her father''s death, as she embarks on a journey of self-discovery through new friendships and experiences.'),
(122, 'The Horse and His Boy', '9780064471060', 'Penguin Group (USA) LLC', 1, 1954, 12, 10, 10, 'Rush Rhees', 'Part of C.S. Lewis''s "The Chronicles of Narnia," this fantasy tale follows Shasta, a young boy, and Bree, a talking horse, as they journey to Narnia, encountering adventures and discovering their true identities.'),
(123, 'Last Sacrifice', '9781595143068', 'Amazon Digital Services, Inc.', 1, 2010, 13, 10, 10, 'Rush Rhees', 'The final installment in Richelle Mead''s "Vampire Academy" series, it concludes the story of Rose Hathaway as she faces political intrigue, battles, and personal challenges in the vampire world.'),
(124, 'Little House on the Prairie', '9780064400022', 'HarperCollins Publishers', 1, 1935, 14, 10, 10, 'Rush Rhees', 'Laura Ingalls Wilder''s autobiographical novel recounts her family''s experiences as pioneers in the American Midwest, highlighting themes of resilience and family bonds.'),
(125, 'The Velveteen Rabbit', '9780385077255', 'Random House LLC', 1, 1922, 15, 10, 10, 'Rush Rhees', 'Margery Williams''s beloved children''s book tells the story of a stuffed rabbit''s desire to become real through the love of a child, exploring themes of love and transformation.'),
(126, 'Zen and the Art of Motorcycle Maintenance', '9780060589462', 'Amazon Digital Services, Inc.', 1, 1974, 16, 10, 10, 'Rush Rhees', 'Robert M. Pirsig''s philosophical novel combines a cross-country motorcycle trip with an exploration of the metaphysics of quality, delving into the nature of values and the human experience.'),
(127, 'Meeting Jesus Again for the First Time', '9780060609177', 'HarperOne', 2, 1995, 17, 10, 10, 'Rush Rhees', 'Marcus Borg examines how historical Jesus scholarship can lead to a more authentic Christian life, offering a contemporary faith free from dogma and focused on spiritual challenge and compassion.'),
(128, 'Reading the Bible Again for the First Time', '9780060609191', 'HarperOne', 2, 2002, 17, 10, 10, 'Rush Rhees', 'Marcus Borg provides a contemporary understanding of the Bible by reconciling historical scholarship with spirituality, offering insights into its ancient meanings and modern relevance.'),
(129, 'Shadow of the Almighty', '9780060622138', 'HarperOne', 2, 1989, 18, 10, 10, 'Rush Rhees', 'The bestselling account of the martyrdom of Jim Elliot and four other missionaries at the hands of the Auca Indians in Ecuador, offering profound insights into faith and sacrifice.'),
(130, 'The Dance of the Dissident Daughter', '9780060645892', 'HarperOne', 2, 2002, 19, 10, 10, 'Rush Rhees', 'Sue Monk Kidd''s spiritual memoir details her feminist awakening and reexamination of her Christian faith, offering inspiring wisdom for women seeking a deeper connection to spirituality.'),
(131, 'C.S. Lewis', '9780060652852', 'HarperOne', 2, 1996, 12, 10, 10, 'Rush Rhees', 'A collection of works and essays by C.S. Lewis, exploring his profound insights on faith, love, and life, as well as his legacy as a 20th-century Christian writer.'),
(132, 'The Screwtape Letters', '9780060652890', 'HarperOne', 2, 2001, 12, 10, 10, 'Rush Rhees', 'In this satirical novel by C.S. Lewis, a senior demon instructs his nephew on the art of tempting humans, offering thought-provoking insights into morality, faith, and human nature.'),
(133, 'Incident Response & Computer Forensics, 2nd Ed.', '9780072226966', 'McGrawHill Osborne Media', 3, 2003, 20, 10, 10, 'Carlson', 'A comprehensive guide to incident response and computer forensics, covering legal, procedural, and technical aspects with real-world case studies.'),
(134, 'C++ Programmer''s Notebook', '9780130887016', 'Prentice Hall', 3, 2002, 21, 10, 10, 'Carlson', 'A practical guide for C++ programmers, offering concise explanations and examples to help developers implement programming concepts effectively.'),
(135, 'Java', '9780131492028', 'Prentice Hall', 3, 2005, 22, 10, 10, 'Carlson', 'A comprehensive introduction to Java programming, covering basic to advanced topics, designed for beginners and intermediate learners.'),
(136, 'Data Structures and Abstractions with Java', '9780132370455', 'Prentice Hall', 3, 2007, 23, 10, 10, 'Carlson', 'A textbook focusing on data structures in Java, emphasizing abstraction and encapsulation in software development.'),
(137, 'Robin Williams Web Design Workshop', '9780201748673', 'Peachpit Press', 3, 2002, 24, 10, 10, 'Carlson', 'A hands-on guide to web design, covering principles of layout, typography, and usability for visually appealing websites.'),
(138, 'Structure and Interpretation of Computer Programs', '9780262510875', 'MIT Press', 3, 1996, 25, 10, 10, 'Carlson', 'A classic computer science textbook that introduces programming principles using the Scheme programming language.'),
(139, 'Turtles, Termites, and Traffic Jams', '9780262680936', 'MIT Press', 3, 1997, 26, 10, 10, 'Carlson', 'Explores the emergence of complex systems from simple behaviors, using examples like traffic patterns and termite colonies.'),
(140, 'The Non-Designer''s Web Book', '9780321303370', 'Peachpit Press', 3, 2006, 27, 10, 10, 'Carlson', 'A guide for beginners on web design principles, including layout, color theory, and typography for effective websites.'),
(141, 'Don''t Make Me Think!', '9780321344755', 'New Riders Press', 3, 2006, 28, 10, 10, 'Carlson', 'A guide to web usability, emphasizing intuitive navigation and user-friendly design to enhance the user experience on websites.'),
(142, 'Reason in History', '9780023513206', 'Macmillan', 4, 1953, 29, 10, 10, 'Rush Rhees', 'Georg Wilhelm Friedrich Hegel''s philosophical exploration of history as a rational process, examining how freedom and reason unfold over time.'),
(143, 'The Presocratics', '9780024266408', 'Macmillan', 4, 1966, 30, 10, 10, 'Rush Rhees', 'An exploration of early Greek philosophers, examining their contributions to metaphysics, ethics, and natural philosophy.'),
(144, 'The Perennial Philosophy', '9780060570583', 'Harper Perennial Modern Classics', 4, 2004, 31, 10, 10, 'Rush Rhees', 'Aldous Huxley examines universal spiritual truths found across major religious traditions, presenting a profound exploration of divine reality.'),
(145, 'The Doors of Perception and Heaven and Hell', '9780060595180', 'Harper Perennial Modern Classics', 4, 2004, 31, 10, 10, 'Rush Rhees', 'Aldous Huxley''s reflections on his experiences with the psychedelic drug mescaline, exploring visionary experiences and the nature of perception.'),
(146, 'Database Design', '8888888888888', 'University of Rochester', 4, 2024, 32, 0, 0, 'Rush Rhees', '261 Course'),
(147, 'Mating in Captivity', '9780060753634', 'Harper', 5, 2006, 33, 10, 10, 'Rush Rhees', 'Esther Perel explores the paradox of intimacy and erotic desire in long-term relationships, offering insights and strategies for rekindling passion.'),
(148, 'DREAM & THE UNDERWORLD', '9780060906825', 'Harper & Row', 5, 1979, 34, 10, 10, 'Rush Rhees', 'James Hillman delves into the psychology of dreams, offering a fresh perspective on their meanings and connections to the unconscious.'),
(149, 'The Dance of Intimacy', '9780060916466', 'Harper & Row', 5, 1990, 35, 10, 10, 'Rush Rhees', 'Harriet Lerner offers guidance on strengthening relationships by fostering intimacy and maintaining a strong sense of self.'),
(150, 'Modern Mind', '9780060084387', 'Harper Perennial', 6, 2002, 36, 10, 10, 'Carlson', 'Peter Watson explores the intellectual history of the 20th century, examining key thinkers, ideas, and movements that shaped modern thought.'),
(151, 'Genome', '9780060894085', 'Harper Perennial', 6, 2006, 37, 10, 10, 'Carlson', 'Matt Ridley explores the human genome, telling the story of one gene from each chromosome and examining its implications for science and society.'),
(152, 'The Best American Science Writing 2002', '9780060936501', 'Harper Perennial', 6, 2002, 37, 10, 10, 'Carlson', 'A collection of thought-provoking essays on cutting-edge scientific developments, written by leading scientists and journalists.'),
(153, 'How to Build a Time Machine', '9780141005348', 'Penguin Books', 6, 2002, 38, 10, 10, 'Carlson', 'Paul Davies explores the possibilities of time travel, blending scientific theory and imaginative speculation.'),
(154, 'Soul of the Sword', '9780684844077', 'Free Press', 7, 2002, 39, 10, 10, 'Carlson', 'A historical exploration of warfare and the evolution of weapons, offering insights into the cultural significance of the sword.'),
(155, 'Nikola Tesla', '9780822549208', 'Lerner Publications', 7, 1994, 40, 10, 10, 'Carlson', 'A biography of Nikola Tesla, highlighting his contributions to science, including alternating current and radio technology.'),
(156, 'John Deere Farm Tractors', '9780879387556', 'Motorbooks International', 7, 1992, 41, 10, 10, 'Carlson', 'A detailed history of John Deere tractors, showcasing their impact on agriculture and innovation.'),
(157, 'Illustrated Guide to the National Electrical Code', '9781401850685', 'Delmar Cengage Learning', 7, 2005, 42, 10, 10, 'Carlson', 'A visual guide to understanding the 2005 edition of the National Electrical Code, suitable for electricians of all levels.'),
(158, 'Romanticism', '9780064300896', 'Harper & Row', 8, 1979, 43, 10, 10, 'Art & Music', 'Hugh Honour examines the influence of Romanticism on Western culture, art, and thought.'),
(159, 'The Visual Arts', '9780131935075', 'Prentice Hall', 8, 2005, 43, 10, 10, 'Art & Music', 'A comprehensive overview of art history, spanning global traditions and examining the evolution of artistic expression.'),
(160, 'Ways of Seeing', '9780140135152', 'Penguin Books', 8, 1972, 44, 10, 10, 'Art & Music', 'John Berger explores the social and psychological implications of visual art, challenging conventional ways of seeing.'),
(161, 'For Lust of Knowing', '9780140289237', 'Penguin Books', 8, 2007, 45, 10, 10, 'Art & Music', 'Robert Irwin delves into the history and interpretation of Islamic culture, exploring how the West perceives and studies it.'),
(162, 'Slider', '9780060580339', 'HarperCollins', 9, 2004, 46, 10, 10, 'Art & Music', 'Patrick Robinson crafts a story about a talented pitcher facing challenges that test his resolve and love for baseball.'),
(163, 'Touching the Void', '9780060730550', 'Harper Perennial', 9, 2004, 47, 10, 10, 'Art & Music', 'Joe Simpson recounts his harrowing survival story after a mountaineering accident in the Andes, offering a gripping tale of courage and endurance.'),
(164, '23 Days in July', '9780306814556', 'Da Capo Press', 9, 2005, 48, 10, 10, 'Art & Music', 'John Wilcockson chronicles the challenges and triumphs of the 2004 Tour de France, focusing on Lance Armstrong''s historic sixth victory.'),
(165, 'A Walk in the Woods', '9780307279460', 'Broadway Books', 9, 2007, 49, 10, 10, 'Art & Music', 'Bill Bryson humorously narrates his attempt to hike the Appalachian Trail, blending adventure with reflections on nature.'),
(166, 'Spanda', '9780026995016', 'Macmillan', 10, 1976, 50, 10, 10, 'Rush Rhees', 'An exploration of philosophical and historical insights on the concept of movement and change in human culture.'),
(167, 'Tyranny of the Majority', '9780029131695', 'Free Press', 10, 1995, 51, 10, 10, 'Rush Rhees', 'Lani Guinier examines the flaws in democratic systems, advocating for reforms to ensure fair representation for minority groups.'),
(168, 'The Origins of the Civil Rights Movement', '9780029221303', 'Free Press', 10, 1986, 52, 10, 10, 'Rush Rhees', 'Aldon D. Morris provides a detailed account of the early civil rights movement, blending scholarly research with firsthand accounts.'),
(169, 'Presidential Power and the Modern Presidents', '9780029227961', 'Free Press', 10, 1991, 53, 10, 10, 'Rush Rhees', 'Richard E. Neustadt explores the dynamics of presidential power in modern U.S. history, offering insights into leadership strategies.'),
(170, 'The Paradox of Choice', '9780060005696', 'Harper Perennial', 12, 2005, 54, 10, 10, 'Carlson', 'Barry Schwartz discusses how excessive choices in modern life can lead to stress and dissatisfaction, providing strategies for simplifying decisions.'),
(171, 'The Innovator''s Dilemma', '9780060521998', 'HarperBusiness', 12, 2003, 55, 10, 10, 'Carlson', 'Clayton Christensen introduces the concept of disruptive innovation, offering insights for businesses to navigate technological and market changes.'),
(172, 'The Big Bing', '9780060529574', 'Harper', 12, 2006, 56, 10, 10, 'Carlson', 'Stanley Bing humorously reflects on corporate culture, blending satire with practical advice for navigating the business world.'),
(173, 'Built to Last', '9780060566104', 'HarperBusiness', 12, 2004, 57, 10, 10, 'Carlson', 'Jim Collins examines enduring companies, identifying principles that contribute to long-term organizational success.'),
(174, 'How to Buy, Sell, and Profit on eBay', '9780062032720', 'HarperBusiness', 13, 2010, 58, 10, 10, 'Rush Rhees', 'Adam Ginsberg offers practical tips for starting a successful business on eBay, sharing insider strategies and personal anecdotes.'),
(175, 'Mission Possible', '9780071348270', 'McGraw-Hill', 13, 1999, 59, 10, 10, 'Rush Rhees', 'Ken Blanchard provides insights into organizational change, focusing on improving existing structures while designing for future success.'),
(176, 'Crucial Conversations', '9780071401944', 'McGraw-Hill', 13, 2002, 60, 10, 10, 'Rush Rhees', 'A guide to handling high-stakes conversations effectively, offering tools to communicate and resolve conflicts with confidence.'),
(177, 'Leadership in Organizations', '9780131494848', 'Prentice Hall', 13, 2006, 61, 10, 10, 'Rush Rhees', 'Gary Yukl provides a comprehensive overview of leadership theories and practices, with practical suggestions for improving managerial effectiveness.');
